function primes_up_to(limit)
{
    let is_prime = bytes::buffer(limit + 1, 1)
    is_prime[0] = 0
    is_prime[1] = 0
    let candidate = 2
    while (candidate * candidate <= limit) {
        if (is_prime[candidate] != 0) {
            fill(is_prime, 0, iter(candidate * candidate, candidate, limit + 1))
        }
        candidate = candidate + 1
    }
    return count(is_prime, 1)
}
